C=[]
def chapter(title,topic,icon,color,objective,hook,story,concepts,evidence,q1,q2,recall,answers,field,refs):
 C.append(dict(title=title,topic=topic,icon=icon,color=color,objective=objective,hook=hook,story=story,concepts=concepts,evidence=evidence,quizzes=[q1,q2],recall=recall,answers=answers,field=field,refs=refs))
def co(title,points,text):return dict(title=title,points=points,text=text)
def q(prompt,options,correct,feedback):return dict(prompt=prompt,options=options,correct=correct,feedback=feedback)
